<script setup lang="ts">
import {ref,watch} from 'vue';import ConfirmDialog from './ConfirmDialog.vue';import {useDraftGuard} from '../lib/useDraftGuard';import {router,useForm} from '@inertiajs/vue3';import CategoryField from './CategoryField.vue';import HistoryPanel from './HistoryPanel.vue';
import Modal from './Modal.vue';import LoadingState from './LoadingState.vue';import Pagination from './Pagination.vue';import {json,money,dateLabel} from '../lib/format';
const props=defineProps<{id:string;catalog:any;embedded?:boolean;version?:number}>();const emit=defineEmits<{close:[];edit:[record:any];payment:[id:string];history:[id:string];remove:[record:any];select:[id:string]}>();
const metadata=useForm<any>({category_id:null,notes:'',manual_classification:null,lock_version:1,command_key:''});const history=ref<any>();
const detail=ref<any>(),results=ref<any>(),query=ref(''),error=ref(''),loading=ref(false),busy=ref(false);let loadNumber=0,searchNumber=0;const saving=ref(false);const draft=useDraftGuard(()=>props.embedded&&metadata.isDirty||false,()=>busy.value||metadata.processing||saving.value,()=>{metadata.reset();metadata.clearErrors();});
defineExpose({selectTransaction:(id:string)=>draft.runAction(()=>emit('select',id))});
async function load(){const number=++loadNumber;error.value='';loading.value=true;try{const result=await json('/transactions/'+props.id);if(number===loadNumber){detail.value=result;metadata.category_id=result.transaction.category_id;metadata.notes=result.transaction.notes||'';metadata.manual_classification=result.transaction.manual_classification;metadata.lock_version=result.transaction.lock_version;metadata.command_key=crypto.randomUUID();metadata.defaults();if(props.embedded){try{const events=await json('/history/transactions/'+props.id);if(number===loadNumber)history.value=events;}catch{if(number===loadNumber)history.value=null;}}}}catch(e:any){if(number===loadNumber)error.value=e.message;}finally{if(number===loadNumber)loading.value=false;}}
watch(()=>props.id,()=>{detail.value=undefined;results.value=undefined;history.value=undefined;query.value='';searchNumber++;load();},{immediate:true});
watch(()=>props.version,()=>{if(!metadata.isDirty&&!metadata.processing)load();});
function setInvestmentClassification(checked:boolean){metadata.manual_classification=checked?(Number(detail.value.transaction.amount_cents)<0?'investment_purchase':'investment_sale'):['investment_purchase','investment_sale'].includes(detail.value.transaction.provider_classification)?'ordinary':null;}
async function search(url?:string){const number=++searchNumber;try{const result=await json(url||'/transactions/'+props.id+'/occurrences?search='+encodeURIComponent(query.value));if(number===searchNumber)results.value=result;}catch(e:any){if(number===searchNumber)error.value=e.message;}}
function mutate(url:string,data:any={},method:'post'|'delete'='post'){draft.runAction(()=>performMutation(url,data,method));}
function performMutation(url:string,data:any={},method:'post'|'delete'='post'){if(busy.value)return;busy.value=true;router.visit(url,{method,data:{command_key:crypto.randomUUID(),...data},preserveScroll:true,onSuccess:load,onFinish:()=>busy.value=false,onNetworkError:()=>{error.value='The connection failed. Try again after reconnecting.';return false;},onError:e=>error.value=Object.values(e).join(' '),onHttpException:r=>{error.value=r.status===409?'This transaction is already attached to another payment. Detach it first.':'Could not save the change. Reload and try again.';return false;}});}
function saveMetadata(){saving.value=true;metadata.patch('/transactions/'+detail.value.transaction.id,{preserveScroll:true,onFinish:()=>saving.value=false,onSuccess:load,onHttpException:(response:any)=>{error.value=response.status===409?'This transaction changed. Your values are still here. Reload before saving.':'The change could not be saved.';return false;}});}
async function loadHistory(url:string){const number=loadNumber;try{const events=await json(url);if(number===loadNumber)history.value=events;}catch(e:any){if(number===loadNumber)error.value=e.message;}}
function categoryPath(id:string){const c=props.catalog.categories.find((c:any)=>c.id===id);return c?(c.parent_id?(props.catalog.categories.find((p:any)=>p.id===c.parent_id)?.name||'Category')+' › ':'')+c.name:'Uncategorized';}
</script>
<template><div class="min-w-0"><component :is="embedded?'section':Modal" :class="embedded?'panel min-w-0':''" :open="true" title="Transaction details" :busy="busy" @close="emit('close')"><div class="p-6"><p v-if="error" role="alert" class="mb-4 text-orange-800">{{error}} <button class="underline" @click="draft.runAction(load)">Reload</button></p><LoadingState v-if="!detail" :loading="loading" label="Loading transaction"/><template v-else><h2 class="text-xl">{{detail.transaction.payee}} <span v-if="detail.transaction.status==='pending'" class="badge">Pending</span></h2><p class="money mt-3 text-2xl" :class="Number(detail.transaction.amount_cents)>0?'text-income':''">{{money(detail.transaction.amount_cents)}}</p><p class="help mt-2">{{dateLabel(detail.transaction.transaction_date)}} · {{catalog.accounts.find((a:any)=>a.id===detail.transaction.account_id)?.name||'Deleted account'}} · {{detail.transaction.source}}</p><p v-if="detail.transaction.source==='provider'" class="help mt-2">Imported payee, amount, and date are read-only. You can edit category, notes, and Budget treatment.</p><form v-if="embedded" class="mt-5 space-y-4 border-t border-line pt-5" @submit.prevent="saveMetadata"><div class="field"><label for="transaction-category">Category</label><CategoryField id="transaction-category" v-model="metadata.category_id" :categories="catalog.categories"/></div><div class="field"><label for="transaction-notes">Notes <span class="help">Optional</span></label><textarea id="transaction-notes" v-model="metadata.notes" rows="3" maxlength="4000"/></div><label class="flex items-start gap-2 rounded-md border border-line p-3 font-normal"><input type="checkbox" class="mt-0.5" :checked="['investment_purchase','investment_sale'].includes(metadata.manual_classification??detail.transaction.provider_classification??'')" @change="setInvestmentClassification(($event.target as HTMLInputElement).checked)"/><span><strong class="block text-xs">Investment purchase or sale</strong><span class="help mt-1 block">Leaves it out of Budget. Use when the bank hasn’t identified an investment trade.</span></span></label><p v-for="message in metadata.errors" class="help text-warning" role="alert">{{message}}</p><button v-if="metadata.isDirty||metadata.processing" class="btn-primary" :disabled="metadata.processing">{{metadata.processing?'Saving…':'Save changes'}}</button></form><template v-else><div class="mt-5 grid grid-cols-2 gap-4"><div><p class="help">Category</p><p>{{categoryPath(detail.transaction.category_id)}}</p></div><div><p class="help">Budget treatment</p><p>{{(detail.transaction.manual_classification||detail.transaction.provider_classification||'ordinary').replaceAll('_',' ')}}</p></div></div><p v-if="detail.transaction.notes" class="mt-4 whitespace-pre-wrap">{{detail.transaction.notes}}</p></template><p v-if="detail.balance_effect" class="help mt-4">Original balance effect: {{money(detail.balance_effect.delta_cents)}} on {{dateLabel(detail.balance_effect.effective_date)}}. Editing or deleting retains this effect.</p><div class="mt-5 flex flex-wrap gap-2"><button class="btn-primary" @click="draft.runAction(()=>emit('edit',detail.transaction))">Edit transaction</button><button class="btn" @click="mutate('/transactions/'+id+'/visibility',{hidden:!detail.transaction.hidden})">{{detail.transaction.hidden?'Unhide':'Hide'}}</button><button v-if="!embedded" class="btn" @click="emit('history',id)">History</button><button class="btn-danger" @click="draft.runAction(()=>emit('remove',detail.transaction))">Delete</button></div>
 <h3 class="mb-3 mt-7 font-medium">Scheduled payment attachment</h3><p class="help">Attaching keeps the payment’s amount and status unchanged. One transaction can be attached to one active payment.</p><div v-for="a in detail.attachments" :key="a.id" class="mt-3 flex items-center justify-between rounded border border-line p-3"><button v-if="a.occurrence" class="text-left hover:underline" @click="emit('payment',a.occurrence.id)">{{a.occurrence.name}} · {{dateLabel(a.occurrence.due_date)}}</button><span v-else>Deleted scheduled payment</span><button class="btn" @click="mutate('/attachments/'+a.id,{},'delete')">Detach</button></div>
 <template v-if="!detail.attachments.length"><form class="mt-4 flex gap-2" @submit.prevent="search()"><input v-model="query" aria-label="Search scheduled payments" placeholder="Find a scheduled payment"/><button class="btn">Search</button></form><div v-for="o in results?.data||[]" :key="o.id" class="flex items-center justify-between border-b border-line py-3"><div>{{o.name}}<p class="help">{{dateLabel(o.due_date)}} · {{money(o.amount_cents)}} · {{o.status.replaceAll('_',' ')}}</p></div><button class="btn" @click="mutate('/occurrences/'+o.id+'/attachments',{transaction_id:id})">Attach</button></div><Pagination :records="results" asynchronous @load="search"/></template>
 <section v-if="embedded" class="mt-6 border-t border-line pt-5"><h3 class="mb-3 font-medium">Change history</h3><HistoryPanel v-if="history" :events="history.data"/><Pagination v-if="history" :records="history" asynchronous @load="loadHistory"/><p v-else class="help">No change history available.</p></section></template></div></component><ConfirmDialog :open="draft.discard.value" title="Discard unsaved transaction changes?" @cancel="draft.cancel" @confirm="draft.confirm">Your category, notes and Budget treatment changes have not been saved.</ConfirmDialog></div></template>
